interface BenchmarkResult {
  model: string;
  category: string;
  score: number;
  latencyMs: number;
  error?: string;
}

interface ModelSummary {
  model: string;
  avgScore: number;
  categoryScores: Record<string, number>;
  totalTests: number;
  errorRate: number;
}

export function aggregateResults(results: BenchmarkResult[]): ModelSummary[] {
  const byModel: Record<string, BenchmarkResult[]> = {};

  for (const r of results) {
    if (!byModel[r.model]) byModel[r.model] = [];
    byModel[r.model].push(r);
  }

  return Object.entries(byModel).map(([model, modelResults]) => {
    const scores = modelResults.map(r => r.score);
    const avgScore = scores.reduce((a, b) => a + b) / scores.length;

    const byCategory: Record<string, number[]> = {};
    for (const r of modelResults) {
      if (!byCategory[r.category]) byCategory[r.category] = [];
      byCategory[r.category].push(r.score);
    }

    const categoryScores = Object.fromEntries(
      Object.entries(byCategory).map(([cat, catScores]) => [
        cat,
        catScores.reduce((a, b) => a + b) / catScores.length,
      ])
    );

    const errors = modelResults.filter(r => r.error).length;

    return {
      model,
      avgScore,
      categoryScores,
      totalTests: modelResults.length,
      errorRate: errors / modelResults.length,
    };
  });
}

export function getBestModel(results: BenchmarkResult[]): string {
  const summaries = aggregateResults(results);
  const best = summaries.sort((a, b) => b.avgScore - a.avgScore)[0];
  return best.model;
}
